/**
 * @name Command injection vulnerability
 * @description Using os.system, subprocess, or similar with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // System command execution sinks
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["popen", "popen2", "popen3", "popen4"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description Using file operations with untrusted input can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access sinks
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name SQL and other injection vulnerabilities
 * @description SQL injection and other injection vulnerabilities from untrusted input
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // SQL execution sinks
    exists(API::CallNode call |
      call = API::moduleImport("sqlite3").getMember(["execute", "executescript"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("psycopg2").getMember(["execute", "executemany"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("MySQLdb").getMember(["execute", "executemany"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"
